    { k: 'resource-pack', label: 'Resource pack URL', desc: 'URL players download the pack from. Empty = none.', t: 'text', def: '', cat: 'Packs', ph: 'https://… (empty = none)' },
    { k: 'resource-pack-sha1', label: 'Resource pack SHA1', desc: 'Expected SHA-1 of the pack file. Empty = skip check.', t: 'text', def: '', cat: 'Packs', ph: '(empty = skip check)' },
    { k: 'resource-pack-prompt', label: 'Resource pack prompt', desc: 'Custom prompt shown with the pack request.', t: 'text', def: '', cat: 'Packs', ph: '(empty)' },
    { k: 'initial-enabled-packs', label: 'Initially enabled packs', desc: 'Comma-separated datapack IDs enabled at world creation.', t: 'text', def: 'vanilla', cat: 'Packs' },
    { k: 'initial-disabled-packs', label: 'Initially disabled packs', desc: 'Comma-separated datapack IDs left disabled.', t: 'text', def: '', cat: 'Packs', ph: '(empty)' },
    { k: 'text-filtering-config', label: 'Text filtering config', desc: 'External chat-filter config. Empty = disabled.', t: 'text', def: '', cat: 'Advanced', ph: '(empty)' },
    { k: 'enable-jmx-monitoring', label: 'JMX monitoring', desc: 'Expose JVM metrics over JMX.', t: 'bool', def: 'false', cat: 'Advanced' },
    { k: 'debug', label: 'Debug', desc: 'Vanilla debug flag. Leave false.', t: 'bool', def: 'false', cat: 'Advanced' },
    { k: 'log-ips', label: 'Log IPs', desc: 'Include player IPs in the server log.', t: 'bool', def: 'true', cat: 'Advanced' }
  ];

  var byKey = {};
  SCHEMA.forEach(function (f) { byKey[f.k] = f; });

  // Explicit field styling: never rely on bare UA defaults (that is what
  // rendered white-on-white). Theme vars with dark fallbacks so inputs and
  // selects stay readable in every panel theme.
  var FIELD_STYLE = {
    width: '100%',
    boxSizing: 'border-box',
    background: 'var(--ks-input-bg, rgba(0,0,0,0.4))',
    border: '1px solid var(--ks-input-border, rgba(255,255,255,0.15))',
    color: 'var(--ks-input-text, var(--ks-body, #e5e7eb))',
    borderRadius: 'var(--ks-input-radius, 8px)',
    padding: '8px 12px',
    fontSize: '13px',
    fontFamily: 'inherit',
    outline: 'none',
    colorScheme: 'dark'
  };
  var OPT_STYLE = { background: '#1f2937', color: '#e5e7eb' };

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function say(m, t) { try { sdk.toast(m, t || 'info'); } catch (e) {} }
  function storeGet() {
    try {
      if (sdk && sdk.storage && sdk.storage.get) return sdk.storage.get('mcprops:action:v2').catch(function () { return null; });
    } catch (e) {}
    return Promise.resolve(null);
  }
  function storeSet(v) {
    try { if (sdk && sdk.storage && sdk.storage.set) sdk.storage.set('mcprops:action:v2', String(v)).catch(function () {}); } catch (e) {}
  }
  function act(name, args) {
    return sdk.runAction(name, { args: args || [] }).then(function (r) {
      if (r && r.ok === false) throw new Error(r.error || r.stderr || ('Action failed: ' + name));
      if (r && r.error && !r.stdout && !r.stderr && r.data == null) throw new Error(r.error);
      return r;
    });
  }
  function isMissingErr(m) { return /404|not found|no such file|ENOENT|does not exist|missing/i.test(String(m || '')); }
  function isGateErr(m) { return /page not enabled/i.test(String(m || '')); }
  function argOk(s) { return typeof s === 'string' && s.length > 0 && s.length <= 200 && ARG_RE.test(s); }
  function pathOf(action) {
    for (var i = 0; i < PATHS.length; i++) if (PATHS[i].action === action) return PATHS[i].path;
    return action;
  }
  function parseProps(text) {
    var map = {}, lines = [];
    String(text == null ? '' : text).split(/\r?\n/).forEach(function (ln) {
      var m = ln.match(/^\s*([^#\s][^=\s]*)\s*=\s*(.*?)\s*$/);
      if (m) {
        if (map[m[1]] === undefined) map[m[1]] = m[2];
        lines.push({ t: 'kv', k: m[1], v: m[2] });
      } else if (/^\s*$/.test(ln)) {
        lines.push({ t: 'blank', raw: ln });
      } else {
        lines.push({ t: 'comment', raw: ln });
      }
    });
    return { map: map, lines: lines };
  }
  function readText(r) {
    if (typeof r === 'string') return r;
    if (r && typeof r.data === 'string') return r.data;
    if (r && typeof r.content === 'string') return r.content;
    if (r && typeof r.stdout === 'string' && r.stdout) return r.stdout;
    if (r && typeof r.stderr === 'string' && r.stderr && !r.stdout) return r.stderr;
    if (r && r.data != null && typeof r.data === 'object') {
      if (typeof r.data.content === 'string') return r.data.content;
      if (typeof r.data.stdout === 'string' && r.data.stdout) return r.data.stdout;
      if (typeof r.data.text === 'string') return r.data.text;
    }
    if (r && r.data != null) { try { return JSON.stringify(r.data); } catch (e) { return String(r.data); } }
    return '';
  }
  function orderedEntries(preferred) {
    var out = [], seen = {};
    [{ action: preferred, path: pathOf(preferred) }].concat(PATHS).forEach(function (e) {
      if (e.action && !seen[e.action]) { seen[e.action] = true; out.push(e); }
    });
    return out;
  }
  function load(preferredAction) {
    var seq = ++S.seq;
    S.loading = true; S.error = ''; S.gate = false; S.missing = false;
    S.trying = ''; S.tryingAction = ''; S.lastErr = ''; render();
    setTimeout(function () {
      if (R.current && R.current.seq === seq && R.current.loading) {
        R.current.loading = false;
        R.current.error = 'Load timed out — the instance may be stopped or the edge is unreachable. Press Reload.';
        render();
      }
    }, 15000);
    storeGet().then(function (stored) {
      if (!R.current || R.current.seq !== seq) return;
      var entries = orderedEntries(preferredAction || stored);
      var missingCount = 0, lastErr = '';
      function attempt(i) {
        if (!R.current || R.current.seq !== seq) return;
        if (i >= entries.length) {
          if (missingCount === entries.length) {
            var fb = entries[0] || PATHS[0];
            S.activeAction = fb.action; S.activePath = fb.path; storeSet(fb.action);
            applyFile('', true, fb);
          } else {
            S.loading = false;
            S.error = lastErr || 'Could not read server.properties from any known location.';
            render();
          }
          return;
        }
        var e = entries[i];
        S.trying = e.path; S.tryingAction = e.action; render();
        function onFail(err) {
          if (!R.current || R.current.seq !== seq) return;
          var msg = (err && err.message) || String(err);
          if (isGateErr(msg)) {
            S.loading = false; S.gate = true; S.error = msg;
            render();
            return;
          }
          if (isMissingErr(msg)) { missingCount++; }
          else { lastErr = msg; S.lastErr = msg; }
          attempt(i + 1);
        }
        var p;
        try { p = act(e.action, []); }
        catch (err) { onFail(err); return; }
        p.then(function (r) {
          if (!R.current || R.current.seq !== seq) return;
          S.lastErr = '';
          S.activeAction = e.action; S.activePath = e.path; storeSet(e.action);
          applyFile(readText(r), false, e);
        }, onFail);
      }
      attempt(0);
    });
  }
  function applyFile(text, missing, entry) {
    var p = parseProps(text);
    S.missing = missing;
    S.activeAction = entry.action; S.activePath = entry.path;
    S.values = {}; S.orig = {}; S.unknownOrder = []; S.busy = {};
    SCHEMA.forEach(function (f) {
      var v = (p.map[f.k] !== undefined) ? p.map[f.k] : f.def;
      S.values[f.k] = v; S.orig[f.k] = v;
    });
    Object.keys(p.map).forEach(function (k) {
      if (!byKey[k]) { S.values[k] = p.map[k]; S.orig[k] = p.map[k]; S.unknownOrder.push(k); }
    });
    S.applySeq = (S.applySeq || 0) + 1;
    S.applyingAll = false;
    S.loading = false; S.error = ''; S.gate = false; render();
  }
  function isMod(k) { return String(S.values[k] == null ? '' : S.values[k]) !== String(S.orig[k] == null ? '' : S.orig[k]); }
  function modKeys() { return Object.keys(S.values).filter(isMod); }
  function fieldDef(k) {
    if (byKey[k]) return byKey[k];
    return { k: k, label: k, desc: 'Custom key from the file (not in the built-in schema).', t: 'text', def: '' };
  }
  function visibleDefs() {
    var q = S.q.trim().toLowerCase();
    var all = SCHEMA.concat(S.unknownOrder.map(fieldDef));
    if (!q) return all;
    return all.filter(function (f) {
      return f.k.toLowerCase().indexOf(q) >= 0
        || String(f.label).toLowerCase().indexOf(q) >= 0
        || String(f.desc).toLowerCase().indexOf(q) >= 0;
    });
  }
  function checkInt(f, v) {
    if (f.t !== 'int') return null;
    if (!/^-?\d+$/.test(String(v).trim())) return f.label + ': enter a whole number.';
    var n = parseInt(String(v).trim(), 10);
    if (f.min !== undefined && n < f.min) return f.label + ': minimum is ' + f.min + '.';
    if (f.max !== undefined && n > f.max) return f.label + ': maximum is ' + f.max + '.';
    return null;
  }
  function normVal(f, v) {
    v = v == null ? '' : String(v);
    if (f.t === 'int') v = v.trim();
    return v;
  }
  function fieldProblem(f, v) {
    v = v == null ? '' : String(v);
    if (f.t === 'int') {
      var bad = checkInt(f, v);
      if (bad) return bad;
    } else if (f.t === 'bool') {
      if (v !== 'true' && v !== 'false') return f.label + ': pick true or false, then Apply.';
    }
    if (!argOk(f.k + '=' + v)) return f.label + ': unsupported characters or too long for the save action — edit this key through the Files page instead.';
    return null;
  }
  function confirmDiscard(n) {
    var msg = 'Discard ' + n + ' pending change' + (n === 1 ? '' : 's') + '?';
    try {
      if (sdk && sdk.confirm) return sdk.confirm(msg).then(function (ok) { return !!ok; }, function () { return false; });
    } catch (e) {}
    try {
      if (typeof confirm === 'function') return Promise.resolve(!!confirm(msg));
    } catch (e2) {}
    return Promise.resolve(false);
  }
  function reloadGuarded() {
    if (S.applyingAll) return;
    var n = modKeys().length;
    if (!n) { load(); return; }
    confirmDiscard(n).then(function (ok) { if (ok && R.current && !R.current.applyingAll) load(); });
  }
  function cancelAll() {
    if (S.applyingAll) return;
    Object.keys(S.values).forEach(function (k) { S.values[k] = S.orig[k]; });
    S.busy = {};
    S.error = '';
    say('Pending changes discarded.', 'info');
    render();
  }
  function applyAll() {
    var keys = modKeys();
    if (!keys.length || S.applyingAll) return;
    if (!S.activePath) { say('No properties file selected yet — reload first.', 'error'); return; }
    S.applyingAll = true; S.error = ''; var tok = ++S.applySeq; render();
    var done = 0, failed = 0, skipped = 0;
    function next(i) {
      if (!R.current || !mounted.current || R.current.applySeq !== tok) return;
      if (i >= keys.length) {
        S.applyingAll = false;
        var probs = failed + skipped;
        S.error = probs ? (probs + ' of ' + keys.length + ' not applied (' + failed + ' failed, ' + skipped + ' rejected: unsupported characters or out of range).') : '';
        say(probs ? ('Finished with ' + failed + ' failure(s), ' + skipped + ' skipped.') : ('Applied ' + done + ' change(s) — restart the server to take effect.'), probs ? 'error' : 'success');
        render();
        return;
      }
      var k = keys[i];
      if (!isMod(k)) { next(i + 1); return; }
      var f = fieldDef(k);
      var v = normVal(f, S.values[k]);
      S.values[k] = v;
      if (checkInt(f, v) || !argOk(k + '=' + v)) { skipped++; next(i + 1); return; }
      S.busy[k] = true; render();
      act('set_prop', [S.activePath, k + '=' + v]).then(function () {
        if (!R.current || !mounted.current || R.current.applySeq !== tok) return;
        delete S.busy[k];
        S.orig[k] = S.values[k];
        S.missing = false;
        done++;
        next(i + 1);
      }, function (e) {
        if (!R.current || !mounted.current || R.current.applySeq !== tok) return;
        delete S.busy[k];
        failed++;
        say('Apply failed for ' + k + ': ' + ((e && e.message) || String(e)), 'error');
        next(i + 1);
      });
    }
    next(0);
  }
  function backup() {
    if (!S.activePath) { say('Reload first so the page knows which file to back up.', 'error'); return; }
    var d = new Date();
    function p(n) { return (n < 10 ? '0' : '') + n; }
    var dflt = 'server-properties-' + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + '-' + p(d.getHours()) + p(d.getMinutes()) + p(d.getSeconds()) + '.bak';
    var name = null;
    try {
      if (sdk && sdk.prompt) {
        sdk.prompt('Back up ' + S.activePath + ' into backups/ as:', dflt).then(function (v) {
          if (v == null || !R.current) return;
          doBackup(String(v).trim());
        });
        return;
      }
    } catch (e) {}
    name = (typeof prompt === 'function') ? prompt('Back up ' + S.activePath + ' into backups/ as:', dflt) : dflt;
    if (name == null) return;
    doBackup(String(name).trim());
    function doBackup(nm) {
      if (!nm) { say('Backup cancelled — empty name.', 'error'); return; }
      if (!argOk(nm) || nm.indexOf('/') >= 0) { say('Backup name must be a plain filename (letters, digits, spaces, . _ -).', 'error'); return; }
      act('backup_props', [nm]).then(function (r) {
        say(readText(r).trim() || ('backed up as backups/' + nm), 'success');
      }, function (e) {
        say('Backup failed: ' + ((e && e.message) || String(e)), 'error');
      });
    }
  }

  React.useEffect(function () {
    mounted.current = true;
    load();
    function onKey(ev) {
      if ((ev.ctrlKey || ev.metaKey) && String(ev.key).toLowerCase() === 's') {
        ev.preventDefault();
        if (R.current && modKeys().length && !R.current.applyingAll) applyAll();
      }
    }
    document.addEventListener('keydown', onKey);
    return function () {
      mounted.current = false;
      document.removeEventListener('keydown', onKey);
    };
  }, []);

  function widget(f, v, dis) {
