  }

  function statusHtml() {
    if (S.loading) {
      var msg = 'Reading <span class="ks-mono">' + esc(S.trying || 'server.properties') + '</span> via saved action <span class="ks-mono">' + esc(S.tryingAction || '…') + '</span>…';
