    if (S.error && !S.activePath) return '<span style="color:var(--ks-bad)">' + esc(S.error) + '</span>';
    var pending = modKeys().length;
    var total = SCHEMA.length + S.unknownOrder.length;
    var st = '<span class="ks-mono">' + esc(S.activePath || 'server.properties') + '</span>'
      + (S.missing ? ' · <span style="color:var(--ks-warn)">not found — showing defaults; applying creates the file.</span>' : ' · ' + esc(String(total)) + ' keys')
      + (pending ? ' · <span style="color:var(--ks-warn)">' + pending + ' pending</span>' : ' · in sync')
      + (S.applyingAll ? ' · applying…' : '');
    if (S.error) st += ' · <span style="color:var(--ks-bad)">' + esc(S.error) + '</span>';
    return st;
  }

  function body() {
    if (S.loading) {
      return el('div', { className: 'ks-card' },
        el('p', { className: 'ks-muted', style: { fontSize: '13px', margin: 0 } }, 'Reading properties…'));
    }
