      return el('div', { className: 'ks-card' },
        el('p', { style: { color: 'var(--ks-bad)', fontSize: '13px', margin: 0 } }, 'Page not enabled for this instance — link the Server Properties page to its template first.'));
    }
    if (S.error && !S.activePath) {
      return el('div', { className: 'ks-card' },
        el('p', { style: { color: 'var(--ks-bad)', fontSize: '13px', margin: '0 0 8px' } }, S.error),
        el('button', { type: 'button', className: 'ks-btn ks-btn-sm', onClick: reloadGuarded }, 'Retry'));
    }
    var defs = visibleDefs();
    if (!defs.length) {
      return el('div', { className: 'ks-card' },
        el('p', { className: 'ks-muted', style: { fontSize: '13px', margin: 0 } }, 'No keys match this filter.'));
    }
    // Single flat card: every key in one list, no category sections.
    return el('div', { className: 'ks-card', style: { padding: '4px 16px 12px' } },
      defs.map(function (f, i) { return row(f, i); }));
  }

  function actionPill() {
    if (S.loading || S.gate || (S.error && !S.activePath)) return null;
    var pending = modKeys().length;
    return el('div', {
      style: {
        position: 'sticky', bottom: '12px', zIndex: 20,
        display: 'flex', justifyContent: 'center',
