    },
      el('div', {
        style: {
          pointerEvents: 'auto', display: 'flex', alignItems: 'center', gap: '8px',
          background: 'var(--ks-card-bg, rgba(17,24,39,0.92))',
          border: '1px solid var(--ks-card-border, rgba(255,255,255,0.12))',
          borderRadius: '9999px', padding: '8px 8px 8px 16px',
          boxShadow: '0 8px 30px rgba(0,0,0,0.45)',
          backdropFilter: 'blur(12px)', WebkitBackdropFilter: 'blur(12px)'
        }
      },
        el('span', { className: 'ks-muted', style: { fontSize: '12px', whiteSpace: 'nowrap' } },
          S.applyingAll ? 'Applying…' : (pending ? (pending + ' pending change' + (pending === 1 ? '' : 's')) : 'No pending changes')),
        el('button', {
          type: 'button', className: 'ks-btn ks-btn-sm',
          style: { borderRadius: '9999px' },
          disabled: S.applyingAll || pending === 0,
          title: 'Discard all pending edits',
          onClick: cancelAll
