  }

  var pending = modKeys().length;
  var blocked = S.gate || (!!S.error && !S.activePath);
  return el('div', { className: 'ks-page' },
    el('div', { className: 'ks-page-header' },
      el('div', { style: { minWidth: 0 } },
        el('h2', { style: { margin: 0, fontSize: '1.3rem', color: 'var(--ks-heading, #fff)' } }, 'Server Properties'),
        el('p', { className: 'ks-muted', style: { fontSize: '12px', margin: '4px 0 0' } },
          'Edit ', el('span', { className: 'ks-mono' }, 'server.properties'),
          ' below — then Apply. Restart the server to take effect.')),
      el('div', { className: 'ks-page-header-actions' },
        el('button', { type: 'button', className: 'ks-btn-header ks-icon-btn', title: 'Reload from disk', 'aria-label': 'Reload', disabled: !!S.applyingAll, onClick: reloadGuarded }, '⟳'),
        el('button', { type: 'button', className: 'ks-btn ks-btn-sm', title: 'Copy the active file into backups/', onClick: backup }, 'Backup'))),
    el('div', { className: 'ks-muted', style: { fontSize: '12px', marginBottom: '10px' }, dangerouslySetInnerHTML: { __html: statusHtml() } }),
    blocked ? null : el('div', { className: 'ks-card', style: { marginBottom: '10px' } },
      el('div', { className: 'ks-muted', style: { fontSize: '11px', textTransform: 'uppercase', letterSpacing: '.05em', marginBottom: '8px' } }, 'Properties file'),
      el('div', { className: 'ks-row', style: { gap: '8px', flexWrap: 'wrap' } },
        PATHS.map(function (e) {
          var active = S.activeAction === e.action || (!S.activeAction && S.trying === e.path);
          return el('button', {
            key: e.action, type: 'button', className: 'ks-btn ks-btn-sm',
            disabled: !!S.applyingAll,
            style: active ? { borderColor: 'var(--ks-info, #38bdf8)', color: 'var(--ks-heading, #fff)' } : undefined,
            onClick: (function (a) {
