                  if (!ok || !R.current || R.current.applyingAll) return;
                  S.activeAction = a; S.activePath = pathOf(a); storeSet(a); load(a);
                });
              };
            })(e.action)
          }, el('span', { className: 'ks-mono' }, e.path),
            (S.activePath === e.path && !S.missing ? ' ●' : ''));
