    blocked ? null : el('div', { className: 'ks-row', style: { gap: '8px', marginBottom: '10px', flexWrap: 'wrap' } },
      el('input', {
        type: 'text', placeholder: 'filter keys…', 'aria-label': 'Filter keys',
        value: S.q, onChange: function (ev) { S.q = ev.target.value; render(); },
        style: Object.assign({}, FIELD_STYLE, { flex: 1, minWidth: '160px', maxWidth: '320px' })
      }),
      el('span', { className: 'ks-muted', style: { fontSize: '11px', marginLeft: 'auto' } },
        pending ? pending + ' pending change' + (pending === 1 ? '' : 's') : 'no pending changes')),
    body(),
    actionPill(),
    el('p', { className: 'ks-muted', style: { fontSize: '11px', margin: '10px 0 0' } },
      'Applies run the saved ', el('span', { className: 'ks-mono' }, 'set_prop'),
      ' action per changed key (comments, blank lines and key order are preserved; a missing key is appended). Restart the server to take effect.'));
}
